{"content": "#!/usr/bin/env python3
"""Validate the H-machine reformulation of Zeilberger's recurrence against
the GROUND_TRUTH solver, then measure the machine's transient on real rows.

Machine (exact reformulation of C0024's Fundamental Recurrence):
    V''_{r,c}(a) = { B_c(a + r - c) }                  (defined values only)
    V'_{r,c}(a)  = { B_c(0) - (r-c) - a }  if >= 0
    V'(a+1) = dec(V'(a))   hence  H_{a+1} = dec(H_a) u {L_a - 1},
    L_a     = mex( V''(a) u H_a ),   H_0 = V'(0),
    dec(X)  = {x-1 : x in X, x >= 1},
    B_r(a)  = L_a   (B_r(a)=0 terminates the row).

Checks:
  V1  machine L_a reproduces solver's f(r+a, r) - (r+a) exactly (all rows r<=R).
  V2  V'' is q_r-periodic from a = sigma_r = max_{c<r} N(c) - r, not before.
  V3  measure u_r - sigma_r and the machine's L-transient from determinism.
"""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from GROUND_TRUTH import chomp

CEN = Path(__file__).resolve().parents[3] / "GROUND_TRUTH/cache/census_50000.tsv"


def load_census():
    N, cls, per = {}, {}, {}
    with open(CEN) as fh:
        fh.readline()
        for line in fh:
            if line.startswith("#") or not line.strip():
                continue
            p = line.rstrip("\n").split("\t")
            r = int(p[0]); cls[r] = p[1]; per[r] = int(p[2]); N[r] = int(p[3])
    return N, cls, per


def main(R=300, AMAX=400):
    N, cls, per = load_census()
    qmax = R + AMAX + R + 10          # B_c(x) needs q = c + x, x up to AMAX + (R-c)
    print(f"building table rmax={R} qmax={qmax} ...")
    F = chomp.table(R, qmax)          # F[q][r'] = f(q, r')
    print("table built")

    def B(c, x):
        q = c + x
        if q > qmax or c > R:
            return None
        f = F[q][c]
        if cls[c] == "stale":
            # stale rows: B defined only while f(q,c) >= q, i.e. b >= 0;
            # beyond deathq f=dconst<q: row terminated -> undefined
            if q >= N[c]:             # N = deathq = first q with carry
                return None
        return f - q

    def dec(S):
        return {x - 1 for x in S if x >= 1}

    def mex(S):
        m = 0
        while m in S:
            m += 1
        return m

    ok = True
    worst_gap = -10**9
    rows_checked = 0
    for r in range(1, R + 1):
        # true B_r from solver
        trueB = {}
        for a in range(0, AMAX):
            q = r + a
            if q > qmax:
                break
            f = F[q][r]
            if cls[r] == "stale" and q >= N[r]:
                break
            trueB[a] = f - q
        if not trueB:
            continue
        amax_row = max(trueB) + 1     # machine must reproduce up to here
        # machine
        H = set()
        for a in range(0, amax_row):
            Vpp = set()
            for c in range(0, r):
                b = B(c, a + r - c)
                if b is not None:
                    Vpp.add(b)
            Vp = set()
            for c in range(0, r):
                v = B(c, 0) - (r - c) - a
                if v >= 0:
                    Vp.add(v)
            if a == 0:
                H = set(Vp)
            S = Vpp | H
            L = mex(S)
            if a in trueB:
                if L != trueB[a]:
                    print(f"MISMATCH r={r} a={a}: machine L={L} solver={trueB[a]}")
                    ok = False
                    break
            elif L == 0:
                pass  # termination beyond solver values: fine
            else:
                print(f"MISMATCH r={r} a={a}: machine defined L={L} but solver row ended")
                ok = False
                break
            if L == 0:
                break
            H = dec(H) | {L - 1}
        rows_checked += 1
        if not ok:
            break
    print(f"V1 machine reproduces solver: {ok}  (rows checked {rows_checked})")

    # V2: sigma_r = max_{c<r} N(c) - r; V'' periodic from there
    sigmas = {}
    for r in range(1, R + 1):
        sigmas[r] = max(N[c] for c in range(0, r)) - r
    # verify V'' q_r-periodic from sigma_r on sample rows
    def Vpp_at(r, a):
        s = set()
        for c in range(0, r):
            b = B(c, a + r - c)
            if b is not None:
                s.add(b)
        return frozenset(s)
    def qr_of(r):
        q = 1
        for c in range(0, r):
            p = per[c]
            from math import gcd
            q = q * p // gcd(q, p)
        return q
    bad = 0
    for r in list(range(1, min(R, 60) + 1)) + [120, 200, 250, 300]:
        if r > R:
            continue
        sr = sigmas[r]
        qr = qr_of(r)
        base = Vpp_at(r, sr)
        for k in (1, 2, 3):
            if Vpp_at(r, sr + k * qr) != base:
                bad += 1
                print(f"  V'' not {qr}-periodic at sigma for r={r} k={k}")
        # and NOT q_r-periodic before sigma (witness only)
        if sr > 0:
            pre = Vpp_at(r, sr - 1)
            if Vpp_at(r, sr - 1 + qr) == pre and sr - 2 >= 0 and Vpp_at(r, sr - 2) != Vpp_at(r, sr - 2 + qr):
                pass
    print(f"V2 V'' periodic from sigma_r: bad={bad}")

    # V3: u_r - sigma_r and machine L-transient from sigma_r
    #   L-transient after determinism: least a0>=sigma with L p-periodic,
    #   using true B (we just read u_r from census: u_r = N[r]-r)
    print("r  class  p_r  sigma_r  u_r  u_r-sigma_r")
    mx = -10**9
    for r in range(1, R + 1):
        u = N[r] - r
        d = u - sigmas[r]
        mx = max(mx, d)
        if r <= 20 or d >= 5 or r % 50 == 0:
            print(f"{r} {cls[r]:5s} {per[r]} {sigmas[r]:7d} {u:5d} {d:+d}")
    print("max u_r - sigma_r over r<=", R, ":", mx)


if __name__ == "__main__":
    R = int(sys.argv[1]) if len(sys.argv) > 1 else 300
    AMAX = int(sys.argv[2]) if len(sys.argv) > 2 else 400
    main(R, AMAX)
