{"content": "#!/usr/bin/env python3
"""Trajectory dump of the H-machine on real chomp rows, around sigma_r.

For chosen rows r: compute V''(a), V'(a), H_a, k_a = L_a from a=0 to a=u_r+8,
annotating sigma_r, u_r, and whether V''(a) has gone periodic.  Goal: see what
H looks like at determinism onset and why k stabilises within a few steps.
"""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from GROUND_TRUTH import chomp

CEN = Path(__file__).resolve().parents[3] / "GROUND_TRUTH/cache/census_50000.tsv"


def load_census():
    N, cls, per = {}, {}, {}
    with open(CEN) as fh:
        fh.readline()
        for line in fh:
            if line.startswith("#") or not line.strip():
                continue
            p = line.rstrip("\n").split("\t")
            r = int(p[0]); cls[r] = p[1]; per[r] = int(p[2]); N[r] = int(p[3])
    return N, cls, per


def main(R, rows, AMAX):
    N, cls, per = load_census()
    qmax = R + AMAX + R + 10
    F = chomp.table(R, qmax)

    def B(c, x):
        q = c + x
        if q > qmax or c > R or x < 0:
            return None
        if cls[c] == "stale" and q >= N[c]:
            return None
        return F[q][c] - q

    def dec(S):
        return {x - 1 for x in S if x >= 1}

    def mex(S):
        m = 0
        while m in S:
            m += 1
        return m

    for r in rows:
        sigma = max(N[c] for c in range(0, r)) - r
        u = N[r] - r
        qr = 1
        from math import gcd
        for c in range(0, r):
            qr = qr * (per[c] or 1) // gcd(qr, per[c] or 1)
        print(f"\n=== r={r} class={cls[r]} p_r={per[r]} sigma={sigma} u={u} "
              f"q_r={qr} diff={u - sigma}")
        H = set()
        for a in range(0, u + 8):
            Vpp = {B(c, a + r - c) for c in range(0, r)}
            Vpp = {v for v in Vpp if v is not None}
            Vp = set()
            for c in range(0, r):
                v = B(c, 0) - (r - c) - a
                if v >= 0:
                    Vp.add(v)
            if a == 0:
                H = set(Vp)
            S = Vpp | H
            k = mex(S)
            tag = []
            if a == sigma:
                tag.append("SIGMA")
            if a == u:
                tag.append("U")
            if a >= sigma:
                tag.append("det")
            print(f"a={a:3d} k={k:2d} V''={sorted(Vpp)!s:22s} V'(a)={sorted(Vp)!s:18s} "
                  f"H={sorted(H)}  {' '.join(tag)}")
            if k == 0:
                break
            H = dec(H) | {k - 1}


if __name__ == "__main__":
    R = int(sys.argv[1])
    rows = [int(x) for x in sys.argv[2].split(",")]
    AMAX = int(sys.argv[3]) if len(sys.argv) > 3 else 60
    main(R, rows, AMAX)
