{"content": "#!/usr/bin/env python3
"""Compact machine trajectory around determinism onset: H as intervals."""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from GROUND_TRUTH import chomp

CEN = Path(__file__).resolve().parents[3] / "GROUND_TRUTH/cache/census_50000.tsv"


def load_census():
    N, cls, per = {}, {}, {}
    with open(CEN) as fh:
        fh.readline()
        for line in fh:
            if line.startswith("#") or not line.strip():
                continue
            p = line.rstrip("\n").split("\t")
            r = int(p[0]); cls[r] = p[1]; per[r] = int(p[2]); N[r] = int(p[3])
    return N, cls, per


def ivals(S):
    out = []
    S = sorted(S)
    for x in S:
        if out and x == out[-1][1] + 1:
            out[-1][1] = x
        else:
            out.append([x, x])
    return "[" + ",".join(f"{a}-{b}" if a != b else f"{a}" for a, b in out) + "]"


def main(R, rows, AMAX, pad=4):
    N, cls, per = load_census()
    qmax = R + AMAX + R + 10
    F = chomp.table(R, qmax)

    def B(c, x):
        q = c + x
        if q > qmax or c > R or x < 0:
            return None
        if cls[c] == "stale" and q >= N[c]:
            return None
        return F[q][c] - q

    def dec(S):
        return {x - 1 for x in S if x >= 1}

    def mex(S):
        m = 0
        while m in S:
            m += 1
        return m

    from math import gcd
    for r in rows:
        sigma = max(N[c] for c in range(0, r)) - r
        u = N[r] - r
        qr = 1
        for c in range(0, r):
            qr = qr * (per[c] or 1) // gcd(qr, per[c] or 1)
        a_lo, a_hi = max(0, sigma - pad), u + 6
        print(f"\n=== r={r} class={cls[r]} p_r={per[r]} sigma={sigma} u={u} "
              f"q_r={qr} diff={u-sigma}   window a in [{a_lo},{a_hi}]")
        H = set()
        for a in range(0, a_hi + 1):
            Vpp = {B(c, a + r - c) for c in range(0, r)}
            Vpp = {v for v in Vpp if v is not None}
            if a == 0:
                Vp0 = set()
                for c in range(0, r):
                    v = B(c, 0) - (r - c)
                    if v >= 0:
                        Vp0.add(v)
                H = set(Vp0)
            k = mex(Vpp | H)
            if a >= a_lo:
                holes = [h for h in range(0, k) if h not in H]
                holes_str = ivals(holes) if holes else "{}"
                excess = [h for h in H if h > k]
                print(f"a={a:4d} k={k:4d} |H|={len(H):4d} H={ivals(H):30s} "
                      f"holes_below_k={holes_str:16s} excess={ivals(excess) if excess else '{}'}"
                      f"{' SIGMA' if a==sigma else ''}{' U' if a==u else ''}")
            if k == 0:
                break
            H = dec(H) | {k - 1}


if __name__ == "__main__":
