{"content": "#!/usr/bin/env python3
"""Abstract machine: max L-transient grouped by realized period.

Conjecture (machine lemma): for input V of period q and any start H0, the
L-transient is bounded by f(p, q) where p is the realized L-period -- i.e.
independent of M.  If true with f quadratic, then bounded periods (secondary
target, observed p<=9) give N(r) <= C*r.
"""
import sys
from itertools import product
from collections import defaultdict
import random


def mex_bits(s: int) -> int:
    m = 0
    while s & (1 << m):
        m += 1
    return m


def run_machine(V, q, H0, horizon=200000):
    seen = {}
    L = []
    H = H0
    a = 0
    while a < horizon:
        st = (a % q, H)
        if st in seen:
            i = seen[st]
            p = a - i
            a0 = i
            while a0 > 0 and L[a0 - 1] == L[a0 - 1 + p]:
                a0 -= 1
            # least period of L divides p; compute it
            for d in range(1, p + 1):
                if p % d == 0 and all(L[x] == L[x + d] for x in range(a0, a - d)):
                    return (a0, d, False)
            return (a0, p, False)
        seen[st] = a
        k = mex_bits(V[a % q] | H)
        L.append(k)
        if k == 0:
            return (None, None, True)
        H = (H >> 1) | (1 << (k - 1))
        a += 1
    raise RuntimeError("horizon")


def sweep_grouped(M, q, by, random_n=None, rng=None):
    """Fill dict by[(q, p)] = max transient.  Exhaustive or random."""
    universe = 1 << (M + 1)
    H_universe = 1 << (M + 2)
    if random_n is None:
        inputs = product(range(universe), repeat=q)
        starts = range(H_universe)
        def iterate():
            for Vt in inputs:
                for H0 in starts:
                    yield Vt, H0
        it = iterate()
    else:
        def iterate():
            for _ in range(random_n):
                Vt = tuple(rng.randrange(universe) for _ in range(q))
                yield Vt, rng.randrange(H_universe)
        it = iterate()
    for Vt, H0 in it:
        t, p, term = run_machine(Vt, q, H0)
        if term:
            continue
        key = (q, p)
        if key not in by or t > by[key]:
            by[key] = t


if __name__ == "__main__":
    by = {}
    # exhaustive small
    for M in range(1, 5):
        for q in range(1, 5):
            n_total = (1 << ((M + 1) * q)) * (1 << (M + 2))
            if n_total > 3_000_000:
                continue
            sweep_grouped(M, q, by)
        print(f"exhaustive M<={M} done", flush=True)
    # random larger
    rng = random.Random(20261002)
    for M in (6, 8, 12, 16, 24):
        for q in (1, 2, 3, 4, 6):
            sweep_grouped(M, q, by, random_n=40000, rng=rng)
        print(f"random M={M} done", flush=True)
    print("\nq p  max_L_transient   (transient / (p+q), /(p*q+q), /(p+1)/(q+1))")
    for (q, p) in sorted(by):
        t = by[(q, p)]
        print(f"q={q} p={p:2d} t={t:5d}   t/(p+q)={t/(p+q):.2f} "
              f"t/(p*q+q)={t/(p*q+q):.2f} t/((p+1)(q+1))={t/((p+1)*(q+1)):.2f}")
