{"content": "#!/usr/bin/env python3
"""Staircase = repeated p-value in consecutive columns.

V''(a) = { f(a+r,c) - (a+r) : c<r } = column q=a+r of f, minus q.  A descending
staircase of length t in the input V''(a), V''(a+1), ... at values v, v-1, ...
means  f(q+i, c_i) - (q+i) = v - i  for q = a+r, i.e.  f(q+i, c_i) = v + q
CONSTANT.  So the staircase number of V'' is exactly the maximum number of
consecutive columns q in which a fixed value p* occurs as some f(q,c).

Measures, on the table f(q,c), q<=Q, c<=R:
  A) for each p*, the max run of consecutive q with p* in {f(q,c): c<=min(q,R)};
     report the global max and the argmax p*.
  B) same but restricted to c < r for the rows r that witness the run (skip:
     row-restriction only shrinks runs, so A is an upper bound).
  C) cross-check vs the machine lock delays u_r - sigma_r.
"""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from GROUND_TRUTH import chomp

def main(R, Q):
    F = chomp.table(R, Q)     # F[q][c]
    # column occupancy: for each q, the set of p-values {f(q,c) : 0<=c<=min(q,R)}
    # but table gives F[q][c] for all c<=R (entries c>q are f(q,q)); use c<=q.
    best_run = 0
    best_p = None
    # runs: for each p*, track current run length of consecutive q
    run = {}
    from collections import defaultdict
    for q in range(0, Q + 1):
        vals = set(F[q][c] for c in range(0, min(q, R) + 1))
        for p in vals:
            run[p] = run.get(p, 0) + 1
            if run[p] > best_run:
                best_run = run[p]
                best_p = p
        # reset runs for p not in this column
        for p in list(run):
            if p not in vals:
                del run[p]
    print(f"table rmax={R} qmax={Q}")
    print(f"A) max run of consecutive q sharing a p-value: {best_run}  (p*={best_p})")

    # distribution of run lengths for p* >= 2 (skip trivial)
    run = {}
    lengths = defaultdict(int)
    maxrun = defaultdict(int)
    for q in range(0, Q + 1):
        vals = set(F[q][c] for c in range(0, min(q, R) + 1))
        for p in vals:
            run[p] = run.get(p, 0) + 1
            if run[p] > maxrun[p]:
                maxrun[p] = run[p]
        for p in list(run):
            if p not in vals:
                lengths[run[p]] += 1
                del run[p]
    for p in list(run):
        lengths[run[p]] += 1
    print("B) run-length histogram (over all completed runs, all p*):")
    for L in sorted(lengths):
        print(f"   run length {L}: {lengths[L]} runs")

    # where does the max run sit?  print columns of the witness
    # recompute witnessing q-range for best_p
    run = 0
    start = None
    wits = []
    for q in range(0, Q + 1):
        vals = set(F[q][c] for c in range(0, min(q, R) + 1))
        if best_p in vals:
            if run == 0:
                start = q
            run += 1
            if run == best_run:
                wits.append((start, q))
        else:
            run = 0
    print(f"witness column ranges for p*={best_p}: {wits}")
    if wits:
        s, e = wits[-1]
        for q in range(s, e + 1):
            cs = [c for c in range(0, min(q, R) + 1) if F[q][c] == best_p]
            print(f"   q={q}: f(q,c)=p* for c in {cs}")


if __name__ == "__main__":
    R = int(sys.argv[1]) if len(sys.argv) > 1 else 300
    Q = int(sys.argv[2]) if len(sys.argv) > 2 else 750
    main(R, Q)
