{"content": "// Definitive falsifier hunt for C0039 over the FULL census tails.
//
// Post-onset, every witness row c of a plug run is in its periodic regime
// (q >= q0 >= M_{r-1} >= N(c)), so its contribution is exactly
//   p* = q + dvals_c[(q - N(c)) mod p_c]   (live rows; stale rows give none).
// A plug run = consecutive columns q sharing p*, each with some witness.
// Admissibility (row r = cstar+1 minimal): q0 >= Mmax[cstar], Mmax[c] =
// max_{c'<=c} N(c').  Report max admissible run over ALL columns q <= QMAX,
// i.e. over the entire 50000-row census.
//
// usage: hunt <census.tsv> <QMAX>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <map>
#include <algorithm>
using namespace std;

struct Row { int N, p; vector<int> d; };

int main(int argc, char** argv) {
    FILE* fh = fopen(argv[1], "r");
    if (!fh) { fprintf(stderr, "no census\n"); return 1; }
    int QMAX = atoi(argv[2]);
    char line[65536];
    fgets(line, sizeof line, fh); // header
    vector<Row> rows(50001);
    vector<char> live(50001, 0);
    vector<long long> Nv(50001, 0);
    while (fgets(line, sizeof line, fh)) {
        if (line[0] == '#' || line[0] == '\n') continue;
        int r, per, N;
        char cls[16], dvals[4096];
        if (sscanf(line, "%d\t%15s\t%d\t%d\t%4095s", &r, &cls, &per, &N, dvals) != 5) continue;
        Nv[r] = N;
        if (strcmp(cls, "live") == 0 && per > 0) {
            live[r] = 1;
            rows[r].N = N; rows[r].p = per;
            char* tok = strtok(dvals, ",");
            while (tok) { rows[r].d.push_back(atoi(tok)); tok = strtok(nullptr, ","); }
        }
    }
    fclose(fh);
    // running max of N
    vector<long long> Mmax(50001, 0);
    long long run = 0;
    for (int c = 0; c <= 50000; c++) { run = max(run, Nv[c]); Mmax[c] = run; }

    // per-column touched pstars
    static int minc[131072];
    static int stamp[131072];
    memset(stamp, 0, sizeof stamp);
    int cur = 0;
    map<long long, pair<int,long long>> prev; // p* -> (runlen, cstar)
    long long best_adm = 0, best_arg_p = 0, best_arg_q0 = 0, best_arg_cs = 0;
    long long best_raw = 0;
    map<long long,long long> adm_hist, raw_hist;
    for (int q = 0; q <= QMAX; q++) {
        cur++;
        vector<int> touched;
        for (int c = 0; c <= 50000; c++) {
            if (!live[c]) continue;
            if (rows[c].N > q) continue;
            long long x = q - rows[c].N;
            int v = rows[c].d[x % rows[c].p];
            long long ps = q + (long long)v;
            if (ps < 0 || ps >= 131072) continue;
            if (stamp[ps] != cur) { stamp[ps] = cur; minc[ps] = c; touched.push_back((int)ps); }
            else if (c < minc[ps]) minc[ps] = c;
        }
        map<long long, pair<int,long long>> nxt;
        for (int ps : touched) {
            auto it = prev.find(ps);
            if (it != prev.end())
                nxt[ps] = {it->second.first + 1, max(it->second.second, (long long)minc[ps])};
            else
                nxt[ps] = {1, (long long)minc[ps]};
        }
        // finalize runs that stopped
        for (auto& kv : prev) {
            if (nxt.find(kv.first) == nxt.end()) {
                long long len = kv.second.first, cs = kv.second.second;
                long long q0 = q - len;
                raw_hist[len]++;
                best_raw = max(best_raw, len);
                if (q0 >= Mmax[cs]) {
                    adm_hist[len]++;
                    if (len > best_adm) { best_adm = len; best_arg_p = kv.first; best_arg_q0 = q0; best_arg_cs = cs; }
                }
            }
        }
        prev.swap(nxt);
    }
    // finalize remaining (window end)
    for (auto& kv : prev) {
        long long len = kv.second.first, cs = kv.second.second;
        long long q0 = (long long)QMAX + 1 - len;
        raw_hist[len]++;
        best_raw = max(best_raw, len);
        if (q0 >= Mmax[cs]) {
            adm_hist[len]++;
            if (len > best_adm) { best_adm = len; best_arg_p = kv.first; best_arg_q0 = q0; best_arg_cs = cs; }
        }
    }
    printf("QMAX=%d\n", QMAX);
    printf("max raw run: %lld\n", best_raw);
    printf("MAX ADMISSIBLE RUN: %lld  (p*=%lld q0=%lld cstar=%lld need q0>=%lld)\n",
           best_adm, best_arg_p, best_arg_q0, best_arg_cs, Mmax[best_arg_cs]);
    printf("admissible run histogram (len: count), len>=4:\n");
    for (auto& kv : adm_hist) if (kv.first >= 4) printf("  %lld: %lld\n", kv.first, kv.second);
    printf("admissible runs >=7 (falsifiers): ");
    long long tot = 0; for (auto& kv : adm_hist) if (kv.first >= 7) tot += kv.second;
    printf("%lld\n", tot);
    return 0;
}
